Вот пример кода, который иллюстрирует некоторые из этих шагов:

```c++
#include <iostream>
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>

// Константы
const int WINDOW_WIDTH = 800;
const int WINDOW_HEIGHT = 600;
const int CELL_SIZE = 20;
const int FIELD_WIDTH = WINDOW_WIDTH / CELL_SIZE;
const int FIELD_HEIGHT = WINDOW_HEIGHT / CELL_SIZE;

// Структуры
struct Position {
    int x;
    int y;
};

struct Snake {
    Position head;
    Position* body;
    int length;
    int direction;
};

struct Apple {
    Position position;
};

struct Field {
    bool** cells;
    int appleCount;
};

// Функции
SDL_Window* createWindow();
SDL_Renderer* createRenderer(SDL_Window* window);
void destroyWindow(SDL_Window* window);
void destroyRenderer(SDL_Renderer* renderer);

void initField(Field* field);
void destroyField(Field* field);

void initSnake(Snake* snake, Position head, int length);
void destroySnake(Snake* snake);

void initApple(Apple* apple, Field* field);

void drawCell(SDL_Renderer* renderer, int x, int y, int color);
void drawSnake(SDL_Renderer* renderer, Snake* snake);
void drawApple(SDL_Renderer* renderer, Apple* apple);

bool isCollision(Position p1, Position p2);

void updateSnake(Snake* snake);
void updateField(Field* field, Snake* snake, Apple* apple);

void handleInput(Snake* snake, SDL_Event* event);

void animate(Field* field, Snake* snake, Apple* apple);

void runGame();

int main(int argc, char* argv[]) {
    SDL_Init(SDL_INIT_VIDEO);

    SDL_Window* window = createWindow();
    SDL_Renderer* renderer = createRenderer(window);

    runGame(renderer, window);

    destroyRenderer(renderer);
    destroyWindow(window);

    SDL_Quit();
    return 0;
}

SDL_Window* createWindow() {
    SDL_Window* window = SDL_CreateWindow(
        "Snake",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        WINDOW_WIDTH, WINDOW_HEIGHT,
        SDL_WINDOW_SHOWN
    );

    if (window == nullptr) {
        std::cerr << "Failed to create window: " << SDL_GetError() << std::endl;
        exit(EXIT_FAILURE);
    }

    return window;
}

SDL_Renderer* createRenderer(SDL_Window* window) {
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    if (renderer == nullptr) {
        std::cerr << "Failed to create renderer: " << SDL_GetError() << std::endl;
        exit(EXIT_FAILURE);
    }

    return renderer;
}

void destroyWindow(SDL_Window* window) {
    SDL_DestroyWindow(window);
}

void destroyRenderer(SDL_Renderer* renderer) {
    SDL_DestroyRenderer(renderer);
}

void initField(Field* field) {
    field->cells = new bool*[FIELD_WIDTH];
    for (int I = 0; I < FIELD_WIDTH; i++) {
        field->cells[i] = new bool[FIELD_HEIGHT];
        for (int j = 0; j < FIELD_HEIGHT; j++) {
            field->cells[i][j] = false;
        }
    }
    field->appleCount = 0;
}

void destroyField(Field* field) {
    for (int I = 0; I < FIELD_WIDTH; i++) {
        delete[] field->cells[i];
    }
    delete[] field->cells;
}

void initSnake(Snake* snake, Position head, int length) {
    snake->head = head;
    snake->body = new Position[length];
    for (int I = 0; I < length; i++) {
        snake->body[i] = head;
    }
    snake->length = length;
    snake->direction = 0;
}

void destroySnake(Snake* snake) {
    delete[] snake->body;
}

void initApple(Apple* apple, Field* field) {
    int x, y;
    do {
        x = rand() % FIELD_WIDTH;
        y = rand() % FIELD_HEIGHT;
    } while (field->cells[x][y]);

    apple->position.x = x;
    apple->position.y = y;
    field->cells[x][y] = true;
    field->appleCount++;
}

void drawCell(SDL_Renderer* renderer, int x, int y, int color) {
    SDL_Rect rect = { x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE };
    SDL_SetRenderDrawColor(renderer, color, color, color);
    SDL_RenderFillRect(renderer, &rect);
}

void drawSnake(SDL_Renderer* renderer, Snake* snake) {
    int color = SDL_Color { 255, 255, 255, 255 };

    for (int I = 0; I < snake->length; i++) {
        drawCell(renderer, snake->body[i].x, snake->body[i].y, color);
    }
}

void drawApple(SDL_Renderer* renderer, Apple* apple) {
    int color = SDL_Color { 255, 0, 0, 255 };
    drawCell(renderer, apple->position.x, apple->position.y, color);
}

bool isCollision(Position p1, Position p2) {
    return p1.x == p2.x && p1.y == p2.y;
}

void updateSnake(Snake* snake) {
    Position* newBody = new Position[snake->length + 1];
    for (int I = 0; I < snake->length; i++) {
        newBody[i] = snake->body[i];
    }

    newBody[snake->length] = snake->head;

    delete[] snake->body;
    snake->body = newBody;
    snake->length++;

    switch (snake->direction) {
        case 0: // Up
            snake->head.y--;
            break;
        case 1: // Right
            snake->head.x++;
            break;
        case 2: // Down
            snake->head.y++;
            break;
        case 3: // Left
            snake->head.x--;
            break;
    }
}

void updateField(Field* field, Snake* snake, Apple* apple) {
    for (int I = 0; I < snake->length; i++) {
        field->cells[snake->body[i].x][snake->body[i].y] = true;
    }

    field->cells[apple->position.x][apple->position.y] = false;
    apple->position.x = -1;
    apple->position.y = -1;

    field->appleCount--;

    if (field->appleCount == 0) {
        initApple(apple, field);
    }
}

void handleInput(Snake* snake, SDL_Event* event) {
    switch (event->type) {
        case SDL_KEYDOWN:
            switch (event->key.keysym.sym) {
                case SDLK_UP:
                    snake->direction = 0;
                    break;
                case SDLK_RIGHT:
                    snake->direction = 1;
                    break;
                case SDLK_DOWN:
                    snake->direction = 2;
                    break;
                case SDLK_LEFT:
                    snake->direction = 3;
                    break;
            }
            break;
    }
}

void animate(Field* field, Snake* snake, Apple* apple) {
    SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
    SDL_RenderClear(renderer);

    for (int I = 0; I < FIELD_WIDTH; i++) {
        for (int j = 0; j < FIELD_HEIGHT; j++) {
            if (field->cells[i][j]) {
                drawCell(renderer, i, j, SDL_Color { 50, 50, 50, 255 });
            }
        }
    }

    drawSnake(renderer, snake);
    drawApple(renderer, apple);

    SDL_RenderPresent(renderer);
}

void runGame(SDL_Renderer* renderer, SDL_Window* window) {
    SDL_Event event;
    bool running = true;

    Field field;
    initField(&field);

    Snake snake;
    initSnake(&snake, { FIELD_WIDTH / 2, FIELD_HEIGHT / 2 }, 3);

    Apple apple;
    initApple(&apple, &field);

    while (running) {
        while (SDL_PollEvent(&event)) {
            handleInput(&snake, &event);

            if (event.type == SDL_QUIT) {
                running = false;
            }
        }

        updateSnake(&snake);
        updateField(&field, &snake, &apple);

        animate(&field, &snake, &apple);
    }

    destroySnake(&snake);
    destroyField(&field);
}
```

Это примерный код, который показывает, как можно начать реализацию игры «Змейка» на C с использованием SDL. Вам необходимо будет добавить больше функций, использовать собственные изображения для анимации, и настроить скорость и другие параметры, чтобы получить плавную и увлекательную игру.

